   pure subroutine pcm_grad_item_02(ij, c, nshell, nao, natm, maxnp, sh_np, sh_ao, sh_at, sh_e, sh_c, sh_r, npair, p_i, p_j, npts, pts, zk, ptatm, q, dmat, nch, nlane, gp)
      !! One (shell pair, share of the points)'s PCM gradient block, lane-
      !! accumulated exactly as trc_1e_grad_k02's own item -- the old
      !! trc_pcm_grad_driver.inc's pcm_grad_item, specialised to this class
      !! (no sh_l, no runtime dispatch).
      !$acc routine seq
      integer,  intent(in)  :: ij, c
      integer,  intent(in)  :: nshell, nao, natm, maxnp, npair, npts, nch, nlane
      integer,  intent(in)  :: sh_np(nshell), sh_ao(nshell), sh_at(nshell)
      real(dp), intent(in)  :: sh_e(maxnp, nshell), sh_c(maxnp, nshell)
      real(dp), intent(in)  :: sh_r(3, nshell)
      integer,  intent(in)  :: p_i(npair), p_j(npair)
      real(dp), intent(in)  :: pts(3, npts), zk(npts), q(npts)
      integer,  intent(in)  :: ptatm(npts)
      real(dp), intent(in)  :: dmat(nao, nao)
      real(dp), intent(inout) :: gp(3, natm, nlane)

      integer  :: ii, jj, a, b, mu, nu, lane, npt, k0
      real(dp) :: wt, ga(3), gb(3)
      real(dp) :: dblk(6)

      ii = p_i(ij); jj = p_j(ij)
      wt = merge(1.0_dp, 2.0_dp, ii == jj)
      lane = mod(ij - 1, nlane) + 1
      npt = (npts - c)/nch + 1
      k0 = c

      ! Affine index, not a running counter: nvfortran 26.5 fails "Missing
      ! increment value" on a counter used as a subscript in this loop
      ! nest once BOTH na and nb exceed 1 (trc_1e_grad_k02's own
      ! work-around, gen_1e.py's emit_grad_split).
      do b = 0, 5
         nu = sh_ao(jj) + b
         do a = 0, 0
            mu = sh_ao(ii) + a
            dblk(1 + a + 1*b) = dmat(mu, nu)
         end do
      end do

      call pcm_grad_02(sh_np(ii), sh_np(jj), sh_e(:, ii), sh_c(:, ii), &
                          sh_e(:, jj), sh_c(:, jj), sh_r(:, ii), sh_r(:, jj), &
                          npt, k0, nch, pts, zk, ptatm, q, natm, wt, dblk, ga, gb, &
                          gp(1:3, 1:natm, lane))

      ! ATOMIC, trc_1e_grad_k02's own reason: two (shell pair, chunk)
      ! items can share both a lane and an atom.
      !$acc atomic update
      gp(1, sh_at(ii), lane) = gp(1, sh_at(ii), lane) + ga(1)
      !$acc atomic update
      gp(2, sh_at(ii), lane) = gp(2, sh_at(ii), lane) + ga(2)
      !$acc atomic update
      gp(3, sh_at(ii), lane) = gp(3, sh_at(ii), lane) + ga(3)
      !$acc atomic update
      gp(1, sh_at(jj), lane) = gp(1, sh_at(jj), lane) + gb(1)
      !$acc atomic update
      gp(2, sh_at(jj), lane) = gp(2, sh_at(jj), lane) + gb(2)
      !$acc atomic update
      gp(3, sh_at(jj), lane) = gp(3, sh_at(jj), lane) + gb(3)
   end subroutine pcm_grad_item_02

   pure subroutine pcm_grad_02(nprim_a, nprim_b, ea, ca, eb, cb, ra, rb, &
                                  npt, k0, kstep, cpt, zk, ptatm, q, natm, &
                                  wt, dblk, ga, gb, gc)
      !! (0|2) PCM surface-integral gradient block: +D:dV/dR of
      !! sum_k q_k erf(zeta_k|r-C_k|)/|r-C_k| over the npt points
      !! k = k0, k0 + kstep, ... -- basis-centre derivative into ga/gb,
      !! point derivative atomically into gc(:, ptatm(k)). See
      !! emit_pcm_grad_class/emit_dc_vrr in scripts/gen_1e.py.
      !$acc routine seq
      integer,  intent(in)  :: nprim_a, nprim_b, npt, k0, kstep, natm
      real(dp), intent(in)  :: ea(nprim_a), ca(nprim_a)
      real(dp), intent(in)  :: eb(nprim_b), cb(nprim_b)
      real(dp), intent(in)  :: ra(3), rb(3)
      real(dp), intent(in)  :: cpt(3, *)     !! point centres
      real(dp), intent(in)  :: zk(*)         !! zeta_k; the Gaussian exponent is zeta_k^2
      integer,  intent(in)  :: ptatm(*)      !! the point's parent atom, 1-based
      real(dp), intent(in)  :: q(*)          !! the surface charge at each point
      real(dp), intent(in)  :: wt, dblk(6)
      real(dp), intent(out)   :: ga(3), gb(3)
      real(dp), intent(inout) :: gc(3, natm)

      integer  :: ip, jp, ic, k, kk, m, pa
      real(dp) :: al, bet, zeta, oo2z, xi, cc
      real(dp) :: px, py, pz, pax, pay, paz, pbx, pby, pbz
      real(dp) :: pcx, pcy, pcz, tval, vpref0, vpref, rab2
      real(dp) :: abx, aby, abz, w2, theta, thm
      real(dp) :: vn(20,0:3), vn0(20)
      real(dp) :: wx(10,0:2), wy(10,0:2), wz(10,0:2)
      real(dp) :: wx0(10), wy0(10), wz0(10)
      real(dp) :: vAp(18)
      real(dp) :: vBp(10)
      real(dp) :: vBm(3)
      real(dp) :: wxt(6), wyt(6), wzt(6)
      real(dp) :: f(0:BOYS_MMAX)

      abx = ra(1) - rb(1); aby = ra(2) - rb(2); abz = ra(3) - rb(3)
      rab2 = abx*abx + aby*aby + abz*abz

      ga = 0.0_dp; gb = 0.0_dp

      do ip = 1, nprim_a
         al = ea(ip)
      do jp = 1, nprim_b
         bet = eb(jp)
         zeta = al + bet
         oo2z = 0.5_dp/zeta
         xi = al*bet/zeta
         cc = ca(ip)*cb(jp)*wt

         px = (al*ra(1) + bet*rb(1))/zeta
         py = (al*ra(2) + bet*rb(2))/zeta
         pz = (al*ra(3) + bet*rb(3))/zeta
         pax = px - ra(1); pay = py - ra(2); paz = pz - ra(3)
         pbx = px - rb(1); pby = py - rb(2); pbz = pz - rb(3)

         vpref0 = 2.0_dp*PI/zeta*exp(-xi*rab2)

         do ic = 1, npt
            kk = k0 + (ic - 1)*kstep
            pcx = px - cpt(1, kk)
            pcy = py - cpt(2, kk)
            pcz = pz - cpt(3, kk)
            w2 = zk(kk)*zk(kk)
            theta = w2/(w2 + zeta)
            tval = theta*zeta*(pcx*pcx + pcy*pcy + pcz*pcz)
            call boys_eval(3, tval, f)
            thm = 1.0_dp
            do m = 1, 3
               thm = thm*theta
               f(m) = f(m)*thm
            end do
            vpref = vpref0*sqrt(theta)

            ! --- m = 3 ---
            vn(1,3) = vpref*f(3)
            ! --- m = 2 ---
            vn(1,2) = vpref*f(2)
            vn(2,2) = pax*vn(1,2) - pcx*vn(1,3)
            vn(3,2) = pay*vn(1,2) - pcy*vn(1,3)
            vn(4,2) = paz*vn(1,2) - pcz*vn(1,3)
            ! --- m = 1 ---
            vn(1,1) = vpref*f(1)
            vn(2,1) = pax*vn(1,1) - pcx*vn(1,2)
            vn(3,1) = pay*vn(1,1) - pcy*vn(1,2)
            vn(4,1) = paz*vn(1,1) - pcz*vn(1,2)
            vn(5,1) = pax*vn(2,1) - pcx*vn(2,2) &
               + 1.0_dp*oo2z*(vn(1,1) - vn(1,2))
            vn(6,1) = pax*vn(3,1) - pcx*vn(3,2)
            vn(7,1) = pax*vn(4,1) - pcx*vn(4,2)
            vn(8,1) = pay*vn(3,1) - pcy*vn(3,2) &
               + 1.0_dp*oo2z*(vn(1,1) - vn(1,2))
            vn(9,1) = pay*vn(4,1) - pcy*vn(4,2)
            vn(10,1) = paz*vn(4,1) - pcz*vn(4,2) &
               + 1.0_dp*oo2z*(vn(1,1) - vn(1,2))
            ! --- m = 0 ---
            vn(1,0) = vpref*f(0)
            vn(2,0) = pax*vn(1,0) - pcx*vn(1,1)
            vn(3,0) = pay*vn(1,0) - pcy*vn(1,1)
            vn(4,0) = paz*vn(1,0) - pcz*vn(1,1)
            vn(5,0) = pax*vn(2,0) - pcx*vn(2,1) &
               + 1.0_dp*oo2z*(vn(1,0) - vn(1,1))
            vn(6,0) = pax*vn(3,0) - pcx*vn(3,1)
            vn(7,0) = pax*vn(4,0) - pcx*vn(4,1)
            vn(8,0) = pay*vn(3,0) - pcy*vn(3,1) &
               + 1.0_dp*oo2z*(vn(1,0) - vn(1,1))
            vn(9,0) = pay*vn(4,0) - pcy*vn(4,1)
            vn(10,0) = paz*vn(4,0) - pcz*vn(4,1) &
               + 1.0_dp*oo2z*(vn(1,0) - vn(1,1))
            vn(11,0) = pax*vn(5,0) - pcx*vn(5,1) &
               + 2.0_dp*oo2z*(vn(2,0) - vn(2,1))
            vn(12,0) = pax*vn(6,0) - pcx*vn(6,1) &
               + 1.0_dp*oo2z*(vn(3,0) - vn(3,1))
            vn(13,0) = pax*vn(7,0) - pcx*vn(7,1) &
               + 1.0_dp*oo2z*(vn(4,0) - vn(4,1))
            vn(14,0) = pax*vn(8,0) - pcx*vn(8,1)
            vn(15,0) = pax*vn(9,0) - pcx*vn(9,1)
            vn(16,0) = pax*vn(10,0) - pcx*vn(10,1)
            vn(17,0) = pay*vn(8,0) - pcy*vn(8,1) &
               + 2.0_dp*oo2z*(vn(3,0) - vn(3,1))
            vn(18,0) = pay*vn(9,0) - pcy*vn(9,1) &
               + 1.0_dp*oo2z*(vn(4,0) - vn(4,1))
            vn(19,0) = pay*vn(10,0) - pcy*vn(10,1)
            vn(20,0) = paz*vn(10,0) - pcz*vn(10,1) &
               + 2.0_dp*oo2z*(vn(4,0) - vn(4,1))

            ! --- dV/dC, m = 2 ---
            wx(1,2) = 2.0_dp*zeta*pcx*vn(1,3)
            wy(1,2) = 2.0_dp*zeta*pcy*vn(1,3)
            wz(1,2) = 2.0_dp*zeta*pcz*vn(1,3)
            ! --- dV/dC, m = 1 ---
            wx(1,1) = 2.0_dp*zeta*pcx*vn(1,2)
            wy(1,1) = 2.0_dp*zeta*pcy*vn(1,2)
            wz(1,1) = 2.0_dp*zeta*pcz*vn(1,2)
            wx(2,1) = pax*wx(1,1) - pcx*wx(1,2) &
               + vn(1,2)
            wy(2,1) = pax*wy(1,1) - pcx*wy(1,2)
            wz(2,1) = pax*wz(1,1) - pcx*wz(1,2)
            wx(3,1) = pay*wx(1,1) - pcy*wx(1,2)
            wy(3,1) = pay*wy(1,1) - pcy*wy(1,2) &
               + vn(1,2)
            wz(3,1) = pay*wz(1,1) - pcy*wz(1,2)
            wx(4,1) = paz*wx(1,1) - pcz*wx(1,2)
            wy(4,1) = paz*wy(1,1) - pcz*wy(1,2)
            wz(4,1) = paz*wz(1,1) - pcz*wz(1,2) &
               + vn(1,2)
            ! --- dV/dC, m = 0 ---
            wx(1,0) = 2.0_dp*zeta*pcx*vn(1,1)
            wy(1,0) = 2.0_dp*zeta*pcy*vn(1,1)
            wz(1,0) = 2.0_dp*zeta*pcz*vn(1,1)
            wx(2,0) = pax*wx(1,0) - pcx*wx(1,1) &
               + vn(1,1)
            wy(2,0) = pax*wy(1,0) - pcx*wy(1,1)
            wz(2,0) = pax*wz(1,0) - pcx*wz(1,1)
            wx(3,0) = pay*wx(1,0) - pcy*wx(1,1)
            wy(3,0) = pay*wy(1,0) - pcy*wy(1,1) &
               + vn(1,1)
            wz(3,0) = pay*wz(1,0) - pcy*wz(1,1)
            wx(4,0) = paz*wx(1,0) - pcz*wx(1,1)
            wy(4,0) = paz*wy(1,0) - pcz*wy(1,1)
            wz(4,0) = paz*wz(1,0) - pcz*wz(1,1) &
               + vn(1,1)
            wx(5,0) = pax*wx(2,0) - pcx*wx(2,1) &
               + vn(2,1) &
               + 1.0_dp*oo2z*(wx(1,0) - wx(1,1))
            wy(5,0) = pax*wy(2,0) - pcx*wy(2,1) &
               + 1.0_dp*oo2z*(wy(1,0) - wy(1,1))
            wz(5,0) = pax*wz(2,0) - pcx*wz(2,1) &
