               + aby*vn0(5) &
               + vn0(12)
            vBp(3) = abx*abx*abz*vn0(1) &
               + abx*abx*vn0(4) &
               + 2.0_dp*abx*abz*vn0(2) &
               + 2.0_dp*abx*vn0(7) &
               + abz*vn0(5) &
               + vn0(13)
            vBp(4) = abx*aby*aby*vn0(1) &
               + 2.0_dp*abx*aby*vn0(3) &
               + abx*vn0(8) &
               + aby*aby*vn0(2) &
               + 2.0_dp*aby*vn0(6) &
               + vn0(14)
            vBp(5) = abx*aby*abz*vn0(1) &
