               + abz*abz*vn0(2) &
               + 2.0_dp*abz*vn0(7) &
               + vn0(16)
            vBp(7) = aby*aby*aby*vn0(1) &
               + 3.0_dp*aby*aby*vn0(3) &
               + 3.0_dp*aby*vn0(8) &
