            pa = ptatm(kk)
            ga(1) = ga(1) - cc*q(kk)*dblk(1)*(2.0_dp*al*vAp(1))
            gb(1) = gb(1) - cc*q(kk)*dblk(1)*(2.0_dp*bet*vBp(1) - 2.0_dp*vBm(1))
            !$acc atomic update
            gc(1,pa) = gc(1,pa) - cc*q(kk)*dblk(1)*wxt(1)
            ga(2) = ga(2) - cc*q(kk)*dblk(1)*(2.0_dp*al*vAp(2))
            gb(2) = gb(2) - cc*q(kk)*dblk(1)*(2.0_dp*bet*vBp(2))
