            gb(3) = gb(3) - cc*q(kk)*dblk(3)*(2.0_dp*bet*vBp(6) - 1.0_dp*vBm(1))
            !$acc atomic update
            gc(3,pa) = gc(3,pa) - cc*q(kk)*dblk(3)*wzt(3)
            ga(1) = ga(1) - cc*q(kk)*dblk(4)*(2.0_dp*al*vAp(10))
            gb(1) = gb(1) - cc*q(kk)*dblk(4)*(2.0_dp*bet*vBp(4))
            !$acc atomic update
            gc(1,pa) = gc(1,pa) - cc*q(kk)*dblk(4)*wxt(4)
            ga(2) = ga(2) - cc*q(kk)*dblk(4)*(2.0_dp*al*vAp(11))
            gb(2) = gb(2) - cc*q(kk)*dblk(4)*(2.0_dp*bet*vBp(7) - 2.0_dp*vBm(2))
            !$acc atomic update
            gc(2,pa) = gc(2,pa) - cc*q(kk)*dblk(4)*wyt(4)
            ga(3) = ga(3) - cc*q(kk)*dblk(4)*(2.0_dp*al*vAp(12))
            gb(3) = gb(3) - cc*q(kk)*dblk(4)*(2.0_dp*bet*vBp(8))
            !$acc atomic update
            gc(3,pa) = gc(3,pa) - cc*q(kk)*dblk(4)*wzt(4)
            ga(1) = ga(1) - cc*q(kk)*dblk(5)*(2.0_dp*al*vAp(13))
            gb(1) = gb(1) - cc*q(kk)*dblk(5)*(2.0_dp*bet*vBp(5))
            !$acc atomic update
            gc(1,pa) = gc(1,pa) - cc*q(kk)*dblk(5)*wxt(5)
