            gb(2) = gb(2) - cc*q(kk)*dblk(5)*(2.0_dp*bet*vBp(8) - 1.0_dp*vBm(3))
            !$acc atomic update
            gc(2,pa) = gc(2,pa) - cc*q(kk)*dblk(5)*wyt(5)
            ga(3) = ga(3) - cc*q(kk)*dblk(5)*(2.0_dp*al*vAp(15))
            gb(3) = gb(3) - cc*q(kk)*dblk(5)*(2.0_dp*bet*vBp(9) - 1.0_dp*vBm(2))
            !$acc atomic update
            gc(3,pa) = gc(3,pa) - cc*q(kk)*dblk(5)*wzt(5)
            ga(1) = ga(1) - cc*q(kk)*dblk(6)*(2.0_dp*al*vAp(16))
            gb(1) = gb(1) - cc*q(kk)*dblk(6)*(2.0_dp*bet*vBp(6))
